package javax.microedition.lcdui.game;import javax.microedition.lcdui.*;
public class Sprite extends Layer {public static final int TRANS_NONE=0,TRANS_MIRROR_ROT180=1,TRANS_MIRROR=2,TRANS_ROT180=3,TRANS_MIRROR_ROT270=4,TRANS_ROT90=5,TRANS_ROT270=6,TRANS_MIRROR_ROT90=7;
 private Image image;private int fw,fh,frame,transform,rx,ry,cx,cy,cw,ch;private int[]sequence;
 public Sprite(Image image){this(image,image.getWidth(),image.getHeight());}public Sprite(Image image,int w,int h){super(w,h);setImage(image,w,h);defineCollisionRectangle(0,0,w,h);}
 public Sprite(Sprite s){this(s.image,s.fw,s.fh);x=s.x;y=s.y;frame=s.frame;transform=s.transform;rx=s.rx;ry=s.ry;cx=s.cx;cy=s.cy;cw=s.cw;ch=s.ch;setVisible(s.isVisible());if(s.sequence!=null)sequence=s.sequence.clone();width=transform>=4?fh:fw;height=transform>=4?fw:fh;}
 public void setImage(Image image,int w,int h){if(image==null||w<1||h<1||image.getWidth()%w!=0||image.getHeight()%h!=0)throw new IllegalArgumentException();this.image=image;fw=w;fh=h;width=transform>=4?h:w;height=transform>=4?w:h;if(frame>=getRawFrameCount())frame=0;sequence=null;}
 public int getRawFrameCount(){return image.getWidth()/fw*(image.getHeight()/fh);}public int getFrameSequenceLength(){return sequence==null?getRawFrameCount():sequence.length;}public int getFrame(){return frame;}public void setFrame(int f){if(f<0||f>=getFrameSequenceLength())throw new IndexOutOfBoundsException();frame=f;}public void nextFrame(){frame=(frame+1)%getFrameSequenceLength();}public void prevFrame(){frame=(frame+getFrameSequenceLength()-1)%getFrameSequenceLength();}
 public void setFrameSequence(int[]s){if(s==null){sequence=null;frame=0;return;}if(s.length==0)throw new IllegalArgumentException();for(int f:s)if(f<0||f>=getRawFrameCount())throw new ArrayIndexOutOfBoundsException();sequence=s.clone();frame=0;}
 public void defineReferencePixel(int x,int y){rx=x;ry=y;}private int refX(){switch(transform){case 0:case 1:return rx;case 2:case 3:return fw-1-rx;case 4:case 6:return ry;default:return fh-1-ry;}}private int refY(){switch(transform){case 0:case 2:return ry;case 1:case 3:return fh-1-ry;case 4:case 5:return rx;default:return fw-1-rx;}}
 public int getRefPixelX(){return x+refX();}public int getRefPixelY(){return y+refY();}public void setRefPixelPosition(int px,int py){x=px-refX();y=py-refY();}public void setTransform(int t){if(t<0||t>7)throw new IllegalArgumentException();int px=getRefPixelX(),py=getRefPixelY();transform=t;width=t>=4?fh:fw;height=t>=4?fw:fh;setRefPixelPosition(px,py);}
 public void defineCollisionRectangle(int x,int y,int w,int h){if(w<0||h<0)throw new IllegalArgumentException();cx=x;cy=y;cw=w;ch=h;}
 public void paint(Graphics g){if(!isVisible())return;int f=sequence==null?frame:sequence[frame];g.drawRegion(image,(f%(image.getWidth()/fw))*fw,(f/(image.getWidth()/fw))*fh,fw,fh,transform,x,y,20);}
 private int sourceX(int dx,int dy){switch(transform){case 0:case 1:return dx;case 2:case 3:return fw-1-dx;case 4:case 5:return dy;default:return fw-1-dy;}}private int sourceY(int dx,int dy){switch(transform){case 0:case 2:return dy;case 1:case 3:return fh-1-dy;case 4:case 6:return dx;default:return fh-1-dx;}}
 private boolean opaque(int px,int py,boolean pixel){int dx=px-x,dy=py-y;if(dx<0||dy<0||dx>=width||dy>=height)return false;int sx=sourceX(dx,dy),sy=sourceY(dx,dy);if(sx<cx||sy<cy||sx>=cx+cw||sy>=cy+ch)return false;if(!pixel)return true;int f=sequence==null?frame:sequence[frame];int[]p=new int[1];image.getRGB(p,0,1,(f%(image.getWidth()/fw))*fw+sx,(f/(image.getWidth()/fw))*fh+sy,1,1);return (p[0]>>>24)!=0;}
 public boolean collidesWith(Sprite s,boolean pixel){if(!isVisible()||!s.isVisible())return false;int l=Math.max(x,s.x),r=Math.min(x+width,s.x+s.width),t=Math.max(y,s.y),b=Math.min(y+height,s.y+s.height);for(int yy=t;yy<b;yy++)for(int xx=l;xx<r;xx++)if(opaque(xx,yy,pixel)&&s.opaque(xx,yy,pixel))return true;return false;}
 public boolean collidesWith(Image im,int ix,int iy,boolean pixel){if(!isVisible())return false;int l=Math.max(x,ix),r=Math.min(x+width,ix+im.getWidth()),t=Math.max(y,iy),b=Math.min(y+height,iy+im.getHeight());int[]p=new int[1];for(int yy=t;yy<b;yy++)for(int xx=l;xx<r;xx++)if(opaque(xx,yy,pixel)){if(!pixel)return true;im.getRGB(p,0,1,xx-ix,yy-iy,1,1);if((p[0]>>>24)!=0)return true;}return false;}
 public boolean collidesWith(TiledLayer tiles,boolean pixel){if(!isVisible()||!tiles.isVisible())return false;return tiles.collides(this,pixel);}}
